-- HexCastCompiler offline installer. Generated by tools/build-installer.js.
-- Copy only this file to the CC computer and run: HCCInstaller [directory]
local payload = table.concat({
__PAYLOAD__
})
local expectedSize = __UNPACKED_SIZE__
local expectedAdler32 = __ADLER32__

local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local values = {}
for i = 1, #alphabet do values[alphabet:sub(i, i)] = i - 1 end

local function fromBase64(source)
    local bytes, bits, buffer = {}, 0, 0
    for i = 1, #source do
        local value = values[source:sub(i, i)]
        if value ~= nil then
            buffer = buffer * 64 + value
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                bytes[#bytes + 1] = string.char(math.floor(buffer / 2 ^ bits) % 256)
                buffer = buffer % 2 ^ bits
            end
        end
    end
    return table.concat(bytes)
end

local function decompress(source)
    local out, position = {}, 1
    while position <= #source do
        local flags = source:byte(position)
        position = position + 1
        for bit = 0, 7 do
            if position > #source then break end
            if math.floor(flags / 2 ^ bit) % 2 == 0 then
                out[#out + 1] = source:byte(position)
                position = position + 1
            else
                local high, low = source:byte(position, position + 1)
                if not low then error("Installer archive is truncated", 0) end
                position = position + 2
                local token = high * 256 + low
                local offset = math.floor(token / 16)
                local length = token % 16 + 3
                if offset < 1 or offset > #out then error("Installer archive is corrupt", 0) end
                local from = #out - offset + 1
                for i = 0, length - 1 do out[#out + 1] = out[from + i] end
            end
        end
    end
    return out
end

local function checkArchive(bytes)
    if #bytes ~= expectedSize then error("Installer archive has the wrong size", 0) end
    local a, b = 1, 0
    for i = 1, #bytes do
        a = (a + bytes[i]) % 65521
        b = (b + a) % 65521
    end
    if b * 65536 + a ~= expectedAdler32 then
        error("Installer archive checksum failed", 0)
    end
end

local function readString(bytes, position, length)
    if length < 0 or position + length - 1 > #bytes then
        error("Installer archive is truncated", 0)
    end
    local chunks = {}
    for start = position, position + length - 1, 1024 do
        local chars = {}
        for i = start, math.min(start + 1023, position + length - 1) do
            chars[#chars + 1] = string.char(bytes[i])
        end
        chunks[#chunks + 1] = table.concat(chars)
    end
    return table.concat(chunks)
end

local function unpackFiles(bytes)
    local position, files = 2, {}
    local count = bytes[1]
    if not count then error("Installer archive is empty", 0) end
    for _ = 1, count do
        local nameLength = bytes[position]
        if not nameLength then error("Installer archive is truncated", 0) end
        position = position + 1
        local name = readString(bytes, position, nameLength)
        position = position + nameLength
        if name:find("/", 1, true) or name:find("\\", 1, true) or name == ".." then
            error("Unsafe filename in installer archive", 0)
        end
        local b1, b2, b3, b4 = bytes[position], bytes[position + 1], bytes[position + 2], bytes[position + 3]
        if not b4 then error("Installer archive is truncated", 0) end
        local length = ((b1 * 256 + b2) * 256 + b3) * 256 + b4
        position = position + 4
        files[#files + 1] = { name = name, contents = readString(bytes, position, length) }
        position = position + length
    end
    if position ~= #bytes + 1 then error("Installer archive has trailing data", 0) end
    return files
end

local preserve = { hexMap = true, ["hccConfig.lua"] = true, ["startup.lua"] = true }

local function uniquePath(base)
    if not fs.exists(base) then return base end
    local suffix = 1
    while fs.exists(base .. suffix) do suffix = suffix + 1 end
    return base .. suffix
end

local function installFile(directory, file)
    local destination = fs.combine(directory, file.name)
    if fs.exists(destination) and preserve[file.name] then
        print("保留 " .. file.name)
        return
    end
    if fs.exists(destination) then
        if fs.isDir(destination) then error(destination .. " is a directory", 0) end
        local old = fs.open(destination, "r")
        if old then
            local current = old.readAll()
            old.close()
            if current == file.contents then
                print("已是最新版 " .. file.name)
                return
            end
        end
    end

    local temporary = uniquePath(destination .. ".hcc-new")
    local handle, reason = fs.open(temporary, "w")
    if not handle then error("Cannot write " .. temporary .. ": " .. tostring(reason), 0) end
    handle.write(file.contents)
    handle.close()

    local backup
    if fs.exists(destination) then
        backup = uniquePath(destination .. ".hcc-backup")
        fs.move(destination, backup)
    end
    local ok, message = pcall(fs.move, temporary, destination)
    if not ok then
        if backup then pcall(fs.move, backup, destination) end
        error("Cannot install " .. file.name .. ": " .. tostring(message), 0)
    end
    print("安装 " .. file.name .. (backup and "（原文件已备份）" or ""))
end

local directory = shell and shell.dir() or "."
if arg and arg[1] then directory = arg[1] end
if fs.exists(directory) then
    if not fs.isDir(directory) then error("Install path is not a directory: " .. directory, 0) end
else
    fs.makeDir(directory)
end

local bytes = decompress(fromBase64(payload))
checkArchive(bytes)
local files = unpackFiles(bytes)
for _, file in ipairs(files) do installFile(directory, file) end
print("HexCastCompiler 安装完成。编辑 " .. fs.combine(directory, "hccConfig.lua") .. " 配置库存方位和槽位。")
print("若首次安装 startup.lua，重启电脑后会启用命令补全。")
